import { DATA } from './content.js';
const ROOT=new URL('./',import.meta.url), route=document.body.dataset.route;
const $=(s,n=document)=>n.querySelector(s), $$=(s,n=document)=>[...n.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const url=(p='/')=>new URL(p.replace(/^\//,''),ROOT).href;
const image=(p,alt='',cls='',eager=false)=>`<img src="${url(p)}" alt="${esc(alt)}" class="${cls}" loading="${eager?'eager':'lazy'}" decoding="async"${eager?' fetchpriority="high"':''}>`;
const ext=(href,label,cls='text-link')=>`<a href="${esc(href)}" target="_blank" rel="noopener noreferrer" class="${cls}">${label}</a>`;
const link=(p,label,cls='',name='')=>`<a href="${url(p)}" class="${cls}"${name?' aria-label="'+esc(name)+'"':''}>${label}</a>`;
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',pin:'<path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-17a3 3 0 0 1 0 6m2 5a5 5 0 0 1 3 4v2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',phone:'<path d="m7 3 3 5-3 3a16 16 0 0 0 6 6l3-3 5 3c0 3-2 5-5 4C8 19 5 16 3 8 2 5 4 3 7 3Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M19 5l-1.5 1.5m-11 11L5 19"/>',waves:'<path d="M2 6q5-4 10 0t10 0M2 12q5-4 10 0t10 0M2 18q5-4 10 0t10 0"/>',tree:'<path d="m12 2 7 9h-4l6 7H3l6-7H5l7-9Zm0 16v4"/>',check:'<path d="m5 12 4 4L19 6"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',plus:'<path d="M12 5v14M5 12h14"/>',mail:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m2 5 10 8L22 5"/>'})[name]||'<circle cx="12" cy="12" r="8"/>'}</svg>`;
const mark=`<svg viewBox="0 0 56 56" fill="none" aria-hidden="true"><path d="M13 30a15 15 0 0 1 30 0M4 36q12-8 24 0t24 0M9 44q9-6 19 0t19 0M28 2v9M7 13l7 6M49 13l-7 6" stroke="currentColor" stroke-width="1.4"/></svg>`;
const logo=()=>link('/',`${mark}<span>Тихая Гавань<small>ОТДЫХ НА ВОЛГЕ</small></span>`,'logo');
const types={cottage:'Коттедж',room:'Номер',bath:'Баня',veranda:'Веранда',event:'Мероприятие'};
const money=c=>c.price?c.price.replace('от ',''): 'По запросу';
const page=path=>DATA.pages.find(p=>p.route===path);
let favorites;try{favorites=JSON.parse(localStorage.getItem('gavan:favorites')||'[]');if(!Array.isArray(favorites))favorites=[];}catch{favorites=[];}
function header(){const nav=[['/razmeshchenie/','Проживание'],['/bani/','Бани и чан'],['/meropriyatiya/','Мероприятия'],['/restoran/','Ресторан'],['/kontakty/','Контакты']];return `<div class="topbar"><div class="wrap"><span>${icon('pin')} Тольятти · полуостров Копылово</span><div><a href="${url('/demo/')}">Демонстрационная версия</a><span class="top-social">${ext('https://t.me/tihqyagavan63','Telegram','')}${ext('https://vk.com/turbaza63','ВКонтакте','')}</span></div></div></div><header class="header"><div class="wrap header-inner">${logo()}<nav id="navigation" aria-label="Основная навигация">${nav.map(([p,t])=>`<a href="${url(p)}" ${route.startsWith(p.slice(0,-1))?'aria-current="page"':''}>${t}</a>`).join('')}<details class="nav-more"><summary>Ещё <span>⌄</span></summary><div>${[['/letnie-verany/','Летние веранды'],['/razmeshchenie/prajs/','Цены'],['/gallery/','Фотогалерея'],['/reviews/','Отзывы'],['/akcii/','Акции'],['/pravila/','Правила проживания']].map(([p,t])=>link(p,t)).join('')}</div></details><a href="tel:+79278925589" class="mobile-nav-phone">+7 (927) 892-55-89</a></nav><div class="header-actions"><a class="header-phone" href="tel:+79278925589">+7 (927) 892-55-89</a><button class="btn btn-small" data-inquire="Отдых в Тихой Гавани">Забронировать ${icon('arrow')}</button><button class="menu-button icon-button" aria-expanded="false" aria-controls="navigation" aria-label="Открыть меню">${icon('menu')}</button></div></div></header>`;}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-top">${logo()}<p>У каждого есть место,<br>куда хочется вернуться.</p><a href="tel:+79278925589" class="footer-phone">+7 (927) 892-55-89 ${icon('arrow')}</a></div><div class="footer-columns"><div><span class="eyebrow">ПРИЕЗЖАЙТЕ В ГОСТИ</span><p>Самарская область, г. Тольятти,<br>полуостров Копылово,<br>ул. Бурлацкая, 11А</p>${link('/kontakty/','Как добраться ↗','text-link')}</div><div><span class="eyebrow">ОТДЫХ</span>${[['/razmeshchenie/kottedzhi/','Коттеджи'],['/razmeshchenie/nomera/','Гостиничные номера'],['/bani/','Бани и банный чан'],['/letnie-verany/','Веранды и беседки']].map(([p,t])=>link(p,t)).join('')}</div><div><span class="eyebrow">ПОЛЕЗНОЕ</span>${[['/razmeshchenie/prajs/','Цены и условия'],['/meropriyatiya/','Мероприятия'],['/reviews/','Отзывы гостей'],['/pravila/','Правила проживания']].map(([p,t])=>link(p,t)).join('')}${ext('https://3d.tg63.ru/zima/3d.html','3D-тур ↗','')}</div><div><span class="eyebrow">МЫ НА СВЯЗИ</span><a href="tel:+79272191586">+7 (927) 219-15-86</a><a href="tel:+78482625589">+7 (8482) 62-55-89</a><a href="mailto:turbaza63@yandex.ru">turbaza63@yandex.ru</a><div class="social-links">${ext('https://t.me/tihqyagavan63','Telegram ↗','')}${ext('https://vk.com/turbaza63','VK ↗','')}${ext('https://wa.me/79272191586','WhatsApp ↗','')}${ext('https://ok.ru/group/51798118826177','ОК ↗','')}</div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} «Тихая Гавань» · Концепция редизайна</span>${link('/politika-konfidenczialnosti/','Конфиденциальность')}${link('/demo/','О демоверсии')}</div><p class="demo-note">Демонстрационный сайт. Доступность, цены и условия подтверждает администрация турбазы. ${ext('https://tg63.ru/','Официальный сайт ↗','')}</p></div></footer><button class="to-top icon-button" aria-label="Вернуться наверх">↑</button>`;}
function card(c){return `<article class="stay-card"><div class="card-visual">${link(c.route+'/',image(c.cover||DATA.images.hero,c.title))}<span class="tag">${types[c.type]}</span>${['room','cottage'].includes(c.type)?`<button class="favorite icon-button ${favorites.includes(c.route)?'is-saved':''}" data-favorite="${c.route}" aria-label="${favorites.includes(c.route)?'Убрать из избранного':'В избранное'}: ${esc(c.title)}" aria-pressed="${favorites.includes(c.route)}">${icon('heart')}</button>`:''}</div><div class="card-content"><div class="card-meta">${c.capacity?`${icon('people')} До ${c.capacity} гостей`:'По предварительной записи'}<span>Тихая Гавань</span></div><h3>${link(c.route+'/',esc(c.title.replace(/^Коттедж |^Веранда /,'')))}</h3><div class="card-bottom"><div><strong>${c.price?'от ':''}${money(c)}</strong><small>${c.price?'цена с исходного сайта*':'Условия уточняйте'}</small></div>${link(c.route+'/',icon('arrow'), 'circle-link','Подробнее: '+c.title)}</div></div></article>`;}
function sectionHead(eyebrow,title,more,href){return `<div class="section-heading"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2></div>${more?link(href,`${more} ${icon('arrow')}`,'text-link'):''}</div>`;}
function searchForm(){return `<form class="search-panel" id="stay-search"><div class="search-title"><span class="eyebrow">ВАШ МАЛЕНЬКИЙ ОТПУСК</span><strong>Когда приедете?</strong></div><label>${icon('calendar')}<span>Заезд<input type="date" name="arrival" aria-label="Дата заезда"></span></label><label>${icon('calendar')}<span>Выезд<input type="date" name="departure" aria-label="Дата выезда"></span></label><label>${icon('people')}<span>Гости<select name="guests" aria-label="Количество гостей">${[2,1,3,4,5,6,8,10,12,16,18].map(n=>`<option value="${n}">${n} ${n===1?'гость':n<5?'гостя':'гостей'}</option>`).join('')}</select></span></label><button class="btn">Найти свой дом ${icon('arrow')}</button><p class="form-error" aria-live="polite"></p></form>`;}
const faq=()=>`<div class="faq"><details><summary>Во сколько заезд и выезд? ${icon('plus')}</summary><p>На официальном сайте указаны заезд с 16:00 и выезд до 14:00. Возможность другого времени согласуйте с администратором.</p></details><details><summary>Можно ли приехать с питомцем? ${icon('plus')}</summary><p>По опубликованным правилам размещение с животными запрещено.</p></details><details><summary>Нужно ли брать принадлежности для мангала? ${icon('plus')}</summary><p>Решётку и шампуры можно привезти с собой. Возможность аренды и стоимость уточните у администратора.</p></details><details><summary>Как узнать стоимость на мои даты? ${icon('plus')}</summary><p>Выберите объект и подготовьте заявку с датами и количеством гостей. Администратор уточнит наличие, итоговую стоимость и условия бронирования.</p></details></div>`;
function home(){const chosen=['/razmeshchenie/kottedzhi/domik-na-volge','/razmeshchenie/kottedzhi/semejnyj','/razmeshchenie/kottedzhi/belyj-dom'];const stays=chosen.map(r=>DATA.catalog.find(c=>c.route===r));const wedding=DATA.catalog.find(c=>c.route==='/letnie-verany/letnyaya-veranda-svadebnaya');return `<section class="hero">${image(DATA.images.hero,'Территория турбазы «Тихая Гавань»','hero-image',true)}<div class="hero-shade"></div><div class="wrap hero-inner"><div class="hero-kicker"><span class="line"></span> ПРИРОДА. ВОЛГА. ВАШЕ ВРЕМЯ.</div><h1>Ближе к природе.<br>Ближе к <em>себе.</em></h1><p>Срубовые дома, тёплые встречи и неспешные<br class="desktop"> дни на берегу Волги. Здесь хорошо быть вместе.</p><div class="hero-buttons">${link('/razmeshchenie/','Выбрать проживание '+icon('arrow'),'btn btn-cream')}${link('/gallery/','Почувствовать атмосферу','hero-text-link')}</div>${ext('https://3d.tg63.ru/zima/3d.html',`<span>360°</span><small>ОГЛЯНИТЕСЬ<br>ВОКРУГ</small>${icon('arrow')}`,'tour-link')}<div class="hero-bottom"><span>${icon('pin')} ПОЛУОСТРОВ КОПЫЛОВО · ТОЛЬЯТТИ</span><span>ОТДЫХ В ЛЮБОЕ ВРЕМЯ ГОДА <span class="scroll-line"></span></span></div></div></section><div class="wrap search-wrap">${searchForm()}</div><section class="section wrap intro"><div><span class="eyebrow">ТИХАЯ ГАВАНЬ — ЭТО СОСТОЯНИЕ</span><h2>Здесь можно<br>никуда <em>не спешить.</em></h2></div><div class="intro-copy"><p>Просыпаться среди деревьев. Смотреть, как меняется Волга. Собраться за одним столом с теми, кто дорог.</p><p class="muted">На полуострове Копылово есть место и для тихого семейного выходного, и для большого праздника. Выбирайте свой ритм — остальное подождёт.</p>${link('/kontakty/','Найти свою гавань '+icon('arrow'),'text-link')}</div></section><div class="wrap fact-row"><div>${icon('waves')}<span>На берегу<br><strong>Волги</strong></span></div><div>${icon('tree')}<span>Среди деревьев<br><strong>Копылово</strong></span></div><div>${icon('people')}<span>Для семьи<br><strong>и друзей</strong></span></div><div>${icon('sun')}<span>В любое<br><strong>время года</strong></span></div></div><section class="section soft-section"><div class="wrap">${sectionHead('ОСТАТЬСЯ ПОДОЛЬШЕ','Дом, в котором<br>хочется <em>остаться.</em>','Весь каталог','/razmeshchenie/')}<div class="home-catalog-tabs" role="group" aria-label="Тип проживания"><button class="pill active" data-home-type="cottage" aria-pressed="true">Коттеджи</button><button class="pill" data-home-type="room" aria-pressed="false">Гостиничные номера</button><span>У каждого дома — своя история</span></div><div class="card-grid" id="home-stays">${stays.map(card).join('')}</div><p class="price-note">* Цены опубликованы на исходном сайте и требуют подтверждения на выбранные даты. ${link('/razmeshchenie/prajs/','Посмотреть прайс →')}</p></div></section><section class="section wrap">${sectionHead('ОТДЫХ В ВАШЕМ РИТМЕ','Делать то,<br>что <em>по душе.</em>','Все возможности','/meropriyatiya/')}<div class="experience-grid">${[['/bani/','Пар, дерево<br>и полное спокойствие','БАНИ И БАННЫЙ ЧАН',DATA.catalog.find(c=>c.route==='/bani/banya-provans')?.cover],['/restoran/','Вкусные моменты<br>в хорошей компании','РЕСТОРАН',page('/restoran').photos[0]],['/letnie-verany/','Длинный день<br>у большой воды','ВЕРАНДЫ И БЕСЕДКИ',DATA.images.river],['/gallery/','Лето, которое<br>хочется продлить','БАССЕЙН И ТЕРРИТОРИЯ',DATA.images.pool]].map(([p,t,k,im])=>link(p,`${image(im,k)}<div><span class="eyebrow">${k}</span><h3>${t}</h3><span class="experience-arrow">${icon('arrow')}</span></div>`,'experience-card')).join('')}</div></section><section class="celebration"><div class="wrap celebration-grid"><div><span class="eyebrow">БОЛЬШИЕ ПОВОДЫ. ТЁПЛЫЕ ВСТРЕЧИ.</span><h2>Важный день.<br><em>Ваши люди.</em><br>Красивое место.</h2><p>Свадьба на берегу, день рождения среди друзей или встреча всей команды. Соберём повод, место и настроение в один незабываемый день.</p>${link('/meropriyatiya/','Спланировать событие '+icon('arrow'),'btn btn-cream')}<div class="occasion-links">${link('/meropriyatiya/svadby/','Свадьбы ↗')}${link('/meropriyatiya/korporativnye-meropriyatiya/','Корпоративы ↗')}${link('/meropriyatiya/dni-rozhdeniya-yubilei/','Дни рождения ↗')}</div></div><div class="celebration-photo">${image(wedding.cover,'Свадебное оформление веранды на турбазе')}<span class="photo-caption">МЕСТО ДЛЯ ВАШЕЙ НОВОЙ ИСТОРИИ</span></div></div></section><section class="section wrap">${sectionHead('ЧЕРЕЗ ОБЪЕКТИВ','Уже хочется <em>сюда.</em>','Все фотографии','/gallery/')}<div class="mosaic">${[DATA.images.river,DATA.images.gallery[0],DATA.images.pool].map((im,i)=>`<button class="gallery-open" data-gallery="home" data-index="${i}" aria-label="Посмотреть фотографию ${i+1}">${image(im,['Терраса над Волгой','Срубовый коттедж','Бассейн на территории'][i])}${icon('expand')}</button>`).join('')}</div></section><section class="section soft-section"><div class="wrap reviews-home">${sectionHead('СЛОВА, КОТОРЫЕ ГРЕЮТ','Сюда <em>возвращаются.</em>','Отзывы гостей','/reviews/')}<div class="review-grid">${reviewCards(3)}</div></div></section><section class="section wrap faq-grid"><div><span class="eyebrow">ПЕРЕД ПОЕЗДКОЙ</span><h2>Всё, что<br>хочется <em>знать.</em></h2><p class="muted">Остались вопросы? Мы рядом.</p><a href="tel:+79278925589" class="text-link">+7 (927) 892-55-89 ${icon('arrow')}</a></div>${faq()}</section>${contactStrip()}`;}
const reviewSummaries=[{name:'Дарья Бочкарева',date:'11 февраля 2024',text:'Гости рассказали о праздновании юбилея большой компанией, помощи сотрудников с размещением и зимних развлечениях для детей.',id:'1879'},{name:'Анна',date:'5 декабря 2023',text:'В отзыве отмечены внимательное отношение администратора, помощь при бронировании и впечатления от ресторана.',id:'1639'},{name:'Елена Зенова',date:'21 июля 2022',text:'Гостям понравились чистота и оснащение дома. В отзыве также упомянут шум от соседей — этот момент стоит обсудить перед поездкой.',id:'224'}];
function reviewCards(n=99){return reviewSummaries.slice(0,n).map(r=>`<article class="review-card"><span class="quote-sign">“</span><p>${r.text}</p><div class="review-person"><span class="avatar">${r.name[0]}</span><div><strong>${r.name}</strong><small>${r.date}</small></div></div><small class="review-source">Краткое содержание опубликованного отзыва</small>${ext('https://tg63.ru/reviews/#'+r.id,'Читать оригинал ↗','text-link')}</article>`).join('');}
function contactStrip(){return `<section class="contact-strip"><div class="wrap"><div><span class="eyebrow">ВАША ГАВАНЬ УЖЕ РЯДОМ</span><h2>Давайте устроим<br><em>ваш хороший день.</em></h2></div><div><button class="btn btn-cream" data-inquire="Помогите подобрать отдых">Помогите с выбором ${icon('arrow')}</button><a href="tel:+79278925589">или позвоните: +7 (927) 892-55-89</a></div></div></section>`;}
function breadcrumb(name,parent){return `<div class="wrap breadcrumbs">${link('/','Главная')}<span>/</span>${parent?`${link(parent[0],parent[1])}<span>/</span>`:''}<span>${esc(name)}</span></div>`;}
function pageHeading(kicker,title,description=''){return `<div class="page-heading wrap"><span class="eyebrow">${kicker}</span><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>`;}
function catalogPage(type){const name=type==='room'?'Гостиничные номера':type==='cottage'?'Коттеджи':'Проживание';return `${breadcrumb(name)}${pageHeading('ВАШ ДОМ У ВОЛГИ',type==='room'?'Побыть вдвоём.<br><em>Или всей семьёй.</em>':'Выберите свою<br><em>Тихую Гавань.</em>','Уютный номер для двоих или отдельный дом для большой компании. Найдите место, которое подойдёт именно вам.')}<section class="wrap catalog-section"><form id="catalog-filters" class="catalog-filters"><div class="filter-type" role="group" aria-label="Тип проживания">${[['all','Всё проживание'],['cottage','Коттеджи'],['room','Номера']].map(([v,t])=>`<button type="button" data-type="${v}" class="pill ${(type||'all')===v?'active':''}" aria-pressed="${(type||'all')===v}">${t}</button>`).join('')}</div><div class="filter-controls"><label class="filter-search">${icon('search')}<input name="search" aria-label="Поиск по названию" placeholder="Название дома или номера"></label><label>Гостей<select name="guests" aria-label="Вместимость"><option value="0">Любое количество</option>${[2,4,6,8,10,12,16,18].map(n=>`<option value="${n}">От ${n} гостей</option>`).join('')}</select></label><label>Сортировка<select name="sort" aria-label="Сортировка"><option value="default">Рекомендуем</option><option value="price-asc">Цена по возрастанию</option><option value="price-desc">Цена по убыванию</option><option value="capacity">Сначала вместительные</option></select></label></div><div class="filter-bottom"><span id="catalog-count" aria-live="polite"></span><label class="check-line"><input type="checkbox" name="saved"> ${icon('heart')} Только избранное</label><button class="text-button" type="reset">Сбросить фильтры</button></div></form><div id="date-context" class="context-note" hidden></div><div class="card-grid catalog-grid" id="catalog-results"></div><p class="price-note">* Цены из каталога официального сайта. Итоговая стоимость и свободные даты подтверждаются администратором.</p></section>${contactStrip()}`;}
function groupPage(type){const isBath=type==='bath',isEvent=type==='event';const data=DATA.catalog.filter(c=>c.type===type);const title=isBath?'Бани и банный чан':isEvent?'Мероприятия':'Летние веранды';return `${breadcrumb(title)}${pageHeading(isBath?'ТЕПЛО, КОТОРОЕ ОСТАЁТСЯ':isEvent?'СОБРАТЬ ТЕХ, КТО ДОРОГ':'БОЛЬШЕ ВОЗДУХА. БОЛЬШЕ ВОЛГИ.',isBath?'Выдохнуть.<br><em>И согреться.</em>':isEvent?'Для любого повода.<br><em>Для ваших людей.</em>':'Ваш день<br><em>на свежем воздухе.</em>',isBath?'Русский пар, отдых в бане и банный чан. Выберите свой способ замедлиться.':isEvent?'От семейного праздника до встречи команды. Выберите формат — обсудим детали, площадку и размещение.':'Террасы у воды, беседки и площадки для встреч. Сезон работы, вместимость и условия аренды уточняйте перед поездкой.')}<section class="wrap section-top-small"><div class="card-grid ${isEvent?'event-grid':''}">${data.map(card).join('')}</div><p class="price-note">${isEvent?'Состав программы и возможность проведения активностей подтверждает администрация.':'Цены и вместимость приведены по каталогу исходного сайта и требуют уточнения.'}</p></section>${contactStrip()}`;}
function detail(c){const isStay=['cottage','room'].includes(c.type),isEvent=c.type==='event';const parent=isStay?['/razmeshchenie/','Проживание']:c.type==='bath'?['/bani/','Бани и чан']:c.type==='veranda'?['/letnie-verany/','Веранды']:['/meropriyatiya/','Мероприятия'];const photos=c.photos?.length?c.photos:[c.cover||DATA.images.hero];const displayTitle=c.title.replace(/^Коттедж |^Веранда /,'');return `${breadcrumb(displayTitle,parent)}<section class="detail-title wrap"><div><span class="eyebrow">${types[c.type].toUpperCase()} · ТИХАЯ ГАВАНЬ</span><h1>${esc(displayTitle)}</h1></div>${c.capacity?`<span class="capacity-badge">${icon('people')} До ${c.capacity} гостей</span>`:''}</section><section class="detail-gallery wrap ${photos.length<3?'few-photos':''}">${photos.slice(0,3).map((im,i)=>`<button class="gallery-open photo-${i}" data-gallery="detail" data-index="${i}" aria-label="Открыть фото ${i+1}: ${esc(c.title)}">${image(im,c.title+' — фото '+(i+1),'',true)}${i===2?`<span class="all-photos">${icon('expand')} Все фото · ${photos.length}</span>`:''}</button>`).join('')}${photos.length<3?`<button class="gallery-all btn btn-cream" data-gallery="detail" data-index="0">${icon('expand')} Фотографии · ${photos.length}</button>`:''}</section><section class="wrap detail-layout"><div><div class="detail-tabs"><a href="#description">Описание</a><a href="#conditions">Условия</a>${ext('https://3d.tg63.ru/zima/3d.html','3D-тур ↗','')}</div><div class="detail-description" id="description"><span class="eyebrow">ПРОСТРАНСТВО ДЛЯ ОТДЫХА</span><h2>${isEvent?'Ваш повод —<br><em>наша площадка.</em>':isStay?'Здесь будет<br><em>по-домашнему.</em>':'Время для<br><em>вашего отдыха.</em>'}</h2>${isEvent?`<p>${eventCopy(c.route)}</p><p class="muted">Оставьте пожелания, дату и количество гостей. Администратор расскажет о возможных площадках, программе и стоимости.</p>`:`<ul class="description-list">${(c.description?.length?c.description:['Фотографии и информация об объекте — с официального сайта «Тихой Гавани». Подробности и условия посещения уточняйте у администратора.']).map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`}${c.services?.length?`<div class="amenities">${c.services.map(t=>`<div>${icon('check')}<span>${esc(t)}</span></div>`).join('')}</div>`:''}</div><div id="conditions" class="conditions"><h3>Полезно перед поездкой</h3>${isStay?`<div class="check-times"><div>${icon('calendar')}<span>Заезд<strong>с 16:00</strong></span></div><div>${icon('calendar')}<span>Выезд<strong>до 14:00</strong></span></div></div><p>Проживание с животными запрещено. Дополнительные услуги, питание, парковочные места и ранний заезд согласуются с администрацией.</p>`:`<p>Дата, продолжительность, состав услуг и окончательная стоимость согласуются с администрацией. Сезонные активности зависят от погоды и доступности.</p>`}${link('/pravila/','Правила пребывания '+icon('arrow'),'text-link')}<div class="detail-external">${c.video?.[0]?ext(c.video[0].replace('/embed/','/watch?v='),'Видео об объекте ↗'):''}${ext(c.source||'https://tg63.ru'+c.route,'Информация на официальном сайте ↗')}</div></div></div><aside class="booking-card"><span class="eyebrow">${isStay?'ВАШ МАЛЕНЬКИЙ ОТПУСК':'ДАВАЙТЕ СПЛАНИРУЕМ'}</span><div class="detail-price">${c.price?'от ':''}<strong>${money(c)}</strong></div><p class="muted small">${c.price?'Цена опубликована на исходном сайте. Уточните тариф на выбранную дату.':'Стоимость и условия — у администратора.'}</p><button class="btn" data-inquire="${esc(c.title)}">${isStay?'Уточнить даты и стоимость':'Обсудить детали'} ${icon('arrow')}</button>${isStay?ext('https://gavan.tg63.ru/','Перейти к бронированию ↗','booking-system'):''}<div class="booking-phone"><span>Поможем с выбором</span><a href="tel:+79278925589">${icon('phone')} +7 (927) 892-55-89</a></div>${c.priceRows?.length?`<details class="tariffs"><summary>Тарифы с исходного сайта ⌄</summary>${c.priceRows.map(p=>`<div><span>${esc(p.label)}</span><strong>${esc(p.value)}</strong></div>`).join('')}<small>Не являются подтверждённой стоимостью бронирования.</small></details>`:''}${isStay?ext('https://secure-payment-gateway.ru/sc/TwgRQcJBAPHEGxVA','Оплата подтверждённой брони ↗','payment-link'):''}</aside></section><section class="soft-section section"><div class="wrap">${sectionHead('ЕЩЁ НЕМНОГО ВДОХНОВЕНИЯ',isStay?'Другие <em>варианты.</em>':'Посмотрите <em>также.</em>','Весь раздел',parent[0])}<div class="card-grid">${DATA.catalog.filter(x=>x.type===c.type&&x.route!==c.route).slice(0,3).map(card).join('')}</div></div></section>`;}
function eventCopy(r){const text={svadby:'Веранды, ресторан и берег Волги — для церемонии, банкета и встречи самых близких. На базе можно обсудить размещение гостей после праздника.', 'korporativnye-meropriyatiya':'Встреча команды за городом: общение, банкет и совместный отдых. Формат и программу можно согласовать с администрацией.',vypusknye:'Выпускной на природе с банкетом и общей программой. Обсудите подходящую площадку, количество гостей и организационные детали.','detskie-prazdniki':'Детский праздник за городом: площадки на территории, активные игры и время всей семьёй. Возраст участников и программу согласуйте заранее.','dni-rozhdeniya-yubilei':'Соберите близких на день рождения или юбилей. На территории есть коттеджи, ресторан, веранды и беседки для разных форматов встречи.','konferenczii-seminary-treningi-obucheniya':'Деловые встречи и обучение в загородной обстановке. Уточните оснащение конференц-зала, питание и варианты размещения участников.','pejntbol-lazertag-gidrobol':'Командные игры на свежем воздухе. Наличие оборудования, возраст участников и формат игры согласуйте с администратором.',kvesty:'Командные квесты и игровые программы на природе. Сценарий, продолжительность и состав группы обсуждаются заранее.','organizacziya-master-klassov':'Творческая встреча или мастер-класс для вашей компании. Тему, ведущего, материалы и площадку необходимо согласовать заранее.','uroki-verhovoj-ezdy':'На сайте базы представлены занятия верховой ездой. Уточните возможность проведения, место встречи и требования к участникам.','kataniya-na-bajdarkah-i-kanoe':'Прогулки по воде на байдарках и каноэ представлены среди активностей базы. Сезон, маршрут и сопровождение уточняйте заранее.',veloprokat:'Велопрогулки по полуострову Копылово. Наличие велосипедов, маршруты и условия проката уточняйте перед приездом.','vyezdnaya-rybalka-arenda-katera':'Рыбалка и аренда катера представлены на официальном сайте. Обсудите маршрут, продолжительность и возможность выхода на воду.',pokatuyshki:'Водные прогулки и развлечения на Волге.'};return text[r.split('/').pop()]||'Отдых на Волге для вашей компании. Актуальные возможности, сезон работы и условия участия уточните у администратора.';}
function restaurant(){const p=page('/restoran');return `${breadcrumb('Ресторан')}${pageHeading('ХОРОШО, КОГДА ВСЕ ЗА ОДНИМ СТОЛОМ','Со вкусом.<br><em>С видом на Волгу.</em>','Завтрак перед прогулкой, семейный обед или банкет в честь важного дня.')}<div class="wrap restaurant-visual">${image(p.photos[0],'Интерьер ресторана «Тихая Гавань»','',true)}<span>РЕСТОРАН «ТИХАЯ ГАВАНЬ»</span></div><section class="section wrap editorial-grid"><div><span class="eyebrow">ОТ ПРОСТОГО ДО ПРАЗДНИЧНОГО</span><h2>У встречи есть<br><em>свой вкус.</em></h2></div><div><p>В ресторане есть уютный зал, бар и банкетный зал с панорамными окнами. Питание и обслуживание мероприятий можно обсудить заранее.</p><p class="muted">Меню, часы работы и стоимость питания уточняйте перед поездкой. Опубликованный на исходном сайте банкетный PDF относится к 2022 году.</p><div class="button-row"><button class="btn" data-inquire="Ресторан и банкет">Обсудить банкет ${icon('arrow')}</button>${link('/menu/','Посмотреть меню ↗','text-link')}</div></div></section><section class="wrap section-top-small"><div class="mosaic">${p.photos.slice(1,4).map((im,i)=>`<button class="gallery-open" data-gallery="restaurant" data-index="${i+1}" aria-label="Интерьер ресторана, фото ${i+2}">${image(im,'Ресторан, интерьер')}${icon('expand')}</button>`).join('')}</div></section>${contactStrip()}`;}
function pricing(){const all=DATA.catalog.filter(c=>['cottage','room'].includes(c.type));const sub=page(route);return `${breadcrumb('Цены и условия')}${pageHeading('ПЛАНИРУЙТЕ СВОЙ ОТДЫХ','Понятно о <em>стоимости.</em>','Итоговая цена зависит от объекта, дат и состава гостей. Свободные даты и стоимость подтверждаются администратором.')}<section class="wrap section-top-small"><div class="notice">${icon('calendar')}<div><strong>Цены требуют уточнения</strong><p>Ниже — опубликованные тарифы исходного сайта. Они могут отличаться от действующих. Для точного расчёта укажите даты и количество гостей.</p></div><button class="btn btn-small" data-inquire="Расчёт стоимости проживания">Получить расчёт ${icon('arrow')}</button></div><div class="price-table-wrap"><table class="price-table"><thead><tr><th>Проживание</th><th>Гостей</th><th>Цена из каталога*</th><th><span class="sr-only">Подробнее</span></th></tr></thead><tbody>${all.map(c=>`<tr><td>${link(c.route+'/',esc(c.title))}<small>${types[c.type]}</small></td><td>до ${c.capacity}</td><td>${c.price||'Уточнить'}</td><td>${link(c.route+'/',icon('arrow'),'circle-link','Подробнее: '+c.title)}</td></tr>`).join('')}</tbody></table></div><p class="price-note">* Данные с tg63.ru, изучены 6 ноября 2026 года. Цены не рассчитаны на выбранные даты и не являются подтверждённой бронью.</p><div class="archive-section"><span class="eyebrow">МАТЕРИАЛЫ ИСХОДНОГО САЙТА</span><h2>Сезонные <em>прайсы.</em></h2><p class="muted">Архивные таблицы сохранены для ознакомления. Период действия и актуальность уточняйте.</p><div class="archive-links">${DATA.pages.filter(p=>p.route.startsWith('/razmeshchenie/prajs/')).map(p=>link(p.route+'/',`${esc(p.title)} ${icon('arrow')}`,route===p.route?'active':'')).join('')}</div>${route!=='/razmeshchenie/prajs'&&sub?`<h3>${esc(sub.title)} · архив</h3>${sub.period?`<p class="price-note">Период исходного прайса: ${esc(sub.period)}</p>`:''}${sub.tables.length?sub.tables.map((table,i)=>`<details class="archive-table" ${i===0?'open':''}><summary>${esc(sub.tableTitles?.[i]||`Тарифы · раздел ${i+1}`)} ⌄</summary><div class="price-table-wrap"><table class="price-table">${table.map((row,i)=>`<tr>${row.map(v=>`<${i?'td':'th'}>${esc(v)}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</table></div></details>`).join(''):`<p>Подробные условия опубликованы на исходной странице.</p>`}${ext(sub.source,'Открыть исходный прайс ↗')}`:''}</div></section>${contactStrip()}`;}
function galleryPage(){return `${breadcrumb('Фотогалерея')}${pageHeading('БЕЗ ЛИШНИХ СЛОВ','Почувствуйте <em>место.</em>','Территория, дома, интерьеры и берег Волги. Фотографии с официального сайта турбазы.')}<section class="wrap section-top-small"><div class="gallery-filter" role="group" aria-label="Категория фотографий">${[['all','Вся база'],['cottage','Коттеджи'],['bath','Бани'],['veranda','Веранды']].map(([v,t])=>`<button class="pill ${v==='all'?'active':''}" data-photo-type="${v}" aria-pressed="${v==='all'}">${t}</button>`).join('')}</div><div class="photo-grid" id="photo-grid"></div></section>${contactStrip()}`;}
function contacts(){return `${breadcrumb('Контакты')}${pageHeading('ТЕПЕРЬ МЫ НЕМНОГО БЛИЖЕ','Найдите свою <em>гавань.</em>','Полуостров Копылово. Волга. И время, которое принадлежит вам.')}<section class="wrap contacts-grid section-top-small"><div class="contacts-info"><span class="eyebrow">ПЛАНИРУЕМ ПОЕЗДКУ</span><h2>До встречи<br><em>на Волге.</em></h2><div class="contact-item">${icon('pin')}<div><small>Наш адрес</small><p>Самарская область, г. Тольятти,<br>п-ов Копылово, ул. Бурлацкая, 11А</p></div></div><div class="contact-item">${icon('phone')}<div><small>Размещение и мероприятия</small><a href="tel:+79278925589">+7 (927) 892-55-89</a><a href="tel:+79272191586">+7 (927) 219-15-86</a><a href="tel:+78482625589">+7 (8482) 62-55-89</a></div></div><div class="contact-item">${icon('mail')}<div><small>Электронная почта</small><a href="mailto:turbaza63@yandex.ru">turbaza63@yandex.ru</a></div></div><div class="button-row">${ext('https://wa.me/79272191586','Написать в WhatsApp ↗','btn')}${ext('https://t.me/tihqyagavan63','Telegram ↗','text-link')}</div></div><div class="map-panel">${image(DATA.images.map,'Схема расположения турбазы с официального сайта')}<div class="map-card">${icon('pin')}<strong>Тихая Гавань</strong><span>Бурлацкая, 11А</span>${ext('https://yandex.ru/maps/?text='+encodeURIComponent('Тихая Гавань Тольятти Бурлацкая 11А'),'Проложить маршрут ↗','btn btn-small')}</div></div></section><section class="wrap section editorial-grid"><div><span class="eyebrow">ОСМОТРИТЕСЬ ЗАРАНЕЕ</span><h2>Как всё<br><em>устроено.</em></h2></div><div><p>Посмотрите карту территории или прогуляйтесь по базе в виртуальном 3D-туре. При планировании дороги ориентируйтесь на актуальный маршрут в картах.</p><div class="button-row">${ext('http://map.tg63.ru/','Схема территории ↗','text-link')}${ext('https://3d.tg63.ru/zima/3d.html','Открыть 3D-тур ↗','text-link')}</div></div></section>${contactStrip()}`;}
function reviews(){return `${breadcrumb('Отзывы')}${pageHeading('ПОСЛЕ ХОРОШИХ ВЫХОДНЫХ','Впечатления <em>гостей.</em>','Здесь — краткие пересказы отзывов с официального сайта с датами и ссылками на оригиналы.')}<section class="wrap section-top-small"><div class="review-grid">${reviewCards()}</div><div class="review-more"><p>Хотите прочитать все отзывы или поделиться впечатлением?</p>${ext('https://tg63.ru/reviews/','Все отзывы на официальном сайте ↗','btn')}<button class="text-button" data-review>Подготовить свой отзыв →</button></div></section>${contactStrip()}`;}
function offers(){return `${breadcrumb('Акции')}${pageHeading('ПОВОД ПРИЕХАТЬ ЕЩЁ РАЗ','Особые <em>предложения.</em>','Действующие предложения на ваши даты уточняйте у администратора.')}<section class="wrap section-top-small"><div class="notice">${icon('calendar')}<div><strong>На исходном сайте есть предложения прошлых сезонов</strong><p>Мы сохранили их как архив. Действие скидок в текущем сезоне не подтверждено.</p></div><button class="btn btn-small" data-inquire="Актуальные акции на мои даты">Узнать об акциях ${icon('arrow')}</button></div><div class="offer-list">${[['Дневной отдых в коттедже','На исходном сайте представлена скидка на дневное пребывание. Список домов и действие предложения уточняйте.'],['Скидка на дома и номера','Архивная акция до 6 марта 2024 года. Указанный период завершён.'],['Праздники на веранде','На сайте представлены предложения для свадеб и банкетов. Условия текущего сезона согласуйте с администрацией.']].map(([t,p],i)=>`<article>${image([DATA.images.gallery[0],DATA.images.hero,DATA.images.river][i],t)}<div><span class="eyebrow">АРХИВ ИСХОДНОГО САЙТА</span><h2>${t}</h2><p>${p}</p>${ext('https://tg63.ru/akcii/','Посмотреть исходное предложение ↗','text-link')}</div></article>`).join('')}</div></section>${contactStrip()}`;}
function menu(){return `${breadcrumb('Меню',['/restoran/','Ресторан'])}${pageHeading('РЕСТОРАН «ТИХАЯ ГАВАНЬ»','К столу —<br><em>с удовольствием.</em>','Банкетное меню и питание для гостей базы.')}<section class="wrap section-top-small menu-layout">${image(page('/restoran').photos[1]||page('/restoran').photos[0],'Ресторан, сервировка')}<div><span class="eyebrow">АРХИВНЫЙ МАТЕРИАЛ · 2022</span><h2>Банкетное <em>меню.</em></h2><p>На официальном сайте опубликовано меню от 1 мая 2022 года. Состав блюд, стоимость и возможность заказа могут измениться.</p>${ext('https://tg63.ru/wp-content/uploads/MenuBanquetTG2022-05-01.pdf','Открыть меню 2022 года · PDF ↗','btn')}<button class="text-link text-button" data-inquire="Актуальное меню и питание">Запросить актуальное меню ${icon('arrow')}</button></div></section>${contactStrip()}`;}
function rules(){return `${breadcrumb('Правила проживания')}${pageHeading('ЧТОБЫ ВСЕМ БЫЛО ХОРОШО','До поездки —<br><em>о главном.</em>','Основные правила по материалам официального сайта. Детали и сезонные условия уточняйте при бронировании.')}<section class="wrap prose section-top-small">${[['Заезд и выезд','Заезд с 16:00, выезд до 14:00. Раннее заселение и поздний выезд согласуются заранее.'],['Размещение с животными','По опубликованным правилам пребывание с животными запрещено.'],['Что взять с собой','Сменную обувь, принадлежности для душа, полотенца, сезонные средства от солнца и насекомых. Для мангала — решётку или шампуры.'],['Питание и дополнительные услуги','Условия питания, парковки, бани, бассейна и проката подтверждаются отдельно. Наличие кухни в доме не означает наличие плиты и кухонной посуды.'],['Бронирование и оплата','Сроки проживания, предоплата, отмена и окончательная стоимость определяются согласованными условиями и договором с администрацией. Оплачивайте только подтверждённую заявку.']].map(([t,p])=>`<article><h2>${t}</h2><p>${p}</p></article>`).join('')}<div class="notice"><div><strong>Подробные документы</strong><p>Полные правила, сезонные ограничения и договор опубликованы на официальном сайте.</p><div class="button-row">${ext('https://tg63.ru/pravila/','Полные правила ↗')}${ext('https://tg63.ru/wp-content/uploads/2024/03/dogovor.pdf','Договор · PDF ↗')}${ext('https://tg63.ru/wp-content/uploads/rekviziti.pdf','Реквизиты · PDF ↗')}</div></div></div></section>`;}
function privacy(){return `${breadcrumb('Конфиденциальность')}${pageHeading('ВАШИ ДАННЫЕ','Просто и <em>прозрачно.</em>')}<section class="wrap prose section-top-small"><article><h2>Демонстрационная версия</h2><p>Этот сайт показывает концепцию редизайна турбазы «Тихая Гавань». Формы подготавливают текст обращения на вашем устройстве. Сайт не отправляет обращения на сервер турбазы и не подтверждает бронирование.</p></article><article><h2>Обращения в администрацию</h2><p>После подготовки заявки вы сами выбираете WhatsApp или почтовую программу и отправляете сообщение. Указанные вами сведения передаются выбранному сервису при переходе к нему.</p></article><article><h2>Избранное</h2><p>Список избранных объектов сохраняется только в этом браузере. Его можно очистить в каталоге, убрав отметки с объектов, или через настройки браузера.</p></article><article><h2>Официальный сайт</h2><p>Правила обработки обращений администрацией опубликованы на сайте турбазы.</p>${ext('https://tg63.ru/politika-konfidenczialnosti/','Политика официального сайта ↗')}</article></section>`;}
function demo(){return `${breadcrumb('О демоверсии')}${pageHeading('КОНЦЕПЦИЯ НОВОГО САЙТА','Новая форма.<br><em>Знакомая гавань.</em>')}<section class="wrap prose section-top-small"><article><h2>Полноценная демонстрация редизайна</h2><p>Каталог, услуги, фотографии и контакты основаны на открытых материалах tg63.ru, изученных 6 ноября 2026 года. Демо создано для презентации нового дизайна администрации турбазы.</p></article><article><h2>Что доступно</h2><p>Подбор проживания, фильтры, избранное, страницы объектов, просмотр фотографий, прайсы, подготовка заявок, ссылки на существующее бронирование, карту и 3D-тур.</p></article><article><h2>Бронирование и актуальность</h2><p>Демо не располагает данными о свободных датах. Цены, сезонные услуги и характеристики подтверждает администрация. Подготовленная заявка не отправляется автоматически.</p></article>${ext('https://tg63.ru/','Официальный сайт турбазы ↗','btn')}</section>`;}
function body(){const c=DATA.catalog.find(c=>c.route===route);if(c)return detail(c);if(route==='/')return home();if(route==='/razmeshchenie')return catalogPage();if(route==='/razmeshchenie/kottedzhi')return catalogPage('cottage');if(route==='/razmeshchenie/nomera')return catalogPage('room');if(route==='/bani')return groupPage('bath');if(route==='/meropriyatiya')return groupPage('event');if(route==='/letnie-verany')return groupPage('veranda');if(route==='/restoran')return restaurant();if(route==='/menu')return menu();if(route==='/gallery')return galleryPage();if(route==='/kontakty')return contacts();if(route==='/reviews')return reviews();if(route==='/akcii')return offers();if(route==='/pravila')return rules();if(route==='/politika-konfidenczialnosti')return privacy();if(route.includes('/prajs')||route.startsWith('/prajs-listy'))return pricing();if(route==='/demo')return demo();if(route==='/booking')return `${pageHeading('ВАШ ОТДЫХ НАЧИНАЕТСЯ ЗДЕСЬ','Спланируем <em>поездку.</em>')}<div class="wrap section-top-small">${searchForm()}<div class="notice"><div><strong>Действующая система бронирования</strong><p>Для просмотра доступности перейдите в сервис турбазы. Для работы с сервисом может понадобиться авторизация.</p>${ext('https://gavan.tg63.ru/','Открыть сервис бронирования ↗','btn')}</div></div></div>`;return `${pageHeading('404','Эта тропинка<br><em>ведёт к началу.</em>','Страница не найдена. Выберите раздел в меню или вернитесь на главную.')}<div class="wrap section-top-small">${link('/','На главную '+icon('arrow'),'btn')}</div>`;}
function dialogs(){return `<dialog id="inquiry-dialog" class="inquiry-dialog"><button class="dialog-close icon-button" aria-label="Закрыть окно">${icon('close')}</button><div id="inquiry-content"></div></dialog><dialog id="lightbox" class="lightbox" aria-label="Просмотр фотографий"><button class="lightbox-close icon-button" aria-label="Закрыть фотографии">${icon('close')}</button><button class="lightbox-prev icon-button" aria-label="Предыдущая фотография">←</button><figure><img alt=""><figcaption></figcaption></figure><button class="lightbox-next icon-button" aria-label="Следующая фотография">→</button></dialog><div class="toast" role="status" aria-live="polite"></div>`;}
$('#app').innerHTML=header()+`<main id="main">${body()}</main>`+footer()+dialogs();
const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
const prettyDate=d=>d?d.split('-').reverse().join('.'):'не указана';
function setupDates(form){const a=$('[name="arrival"]',form),b=$('[name="departure"]',form);if(!a||!b)return;a.min=today();b.min=today();a.addEventListener('change',()=>{b.min=a.value?nextDay(a.value):today();if(b.value&&b.value<=a.value)b.value='';});}
function nextDay(v){const d=new Date(v+'T12:00:00');d.setDate(d.getDate()+1);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
function datesValid(form){const a=$('[name="arrival"]',form)?.value,b=$('[name="departure"]',form)?.value;const error=$('.form-error',form);let msg='';if(a&&a<today())msg='Выберите дату заезда не раньше сегодняшней.';else if(form.dataset.singleDate!=='true'&&((a&&!b)||(!a&&b)))msg='Укажите обе даты: заезд и выезд.';else if(a&&b&&b<=a)msg='Дата выезда должна быть позже даты заезда.';if(error)error.textContent=msg;return !msg;}
const search=$('#stay-search');if(search){setupDates(search);search.addEventListener('submit',e=>{e.preventDefault();if(!datesValid(search))return;const q=new URLSearchParams(new FormData(search));location.href=url('/razmeshchenie/')+'?'+q;});}
let catalogType=route.includes('/kottedzhi')?'cottage':route.includes('/nomera')?'room':'all';
const catalogForm=$('#catalog-filters');
function renderCatalog(){if(!catalogForm)return;const f=new FormData(catalogForm),count=Number(f.get('guests')),query=String(f.get('search')||'').toLocaleLowerCase('ru');let items=DATA.catalog.filter(c=>['cottage','room'].includes(c.type)&&(catalogType==='all'||c.type===catalogType)&&(!count||c.capacity>=count)&&c.title.toLocaleLowerCase('ru').includes(query)&&(!f.has('saved')||favorites.includes(c.route)));const price=c=>Number((c.price||'').replace(/\D/g,''));if(f.get('sort')==='price-asc')items.sort((a,b)=>price(a)-price(b));if(f.get('sort')==='price-desc')items.sort((a,b)=>price(b)-price(a));if(f.get('sort')==='capacity')items.sort((a,b)=>b.capacity-a.capacity);$('#catalog-count').textContent=`Найдено вариантов: ${items.length}`;$('#catalog-results').innerHTML=items.length?items.map(card).join(''):`<div class="empty-state">${icon('search')}<h2>Поищем <em>по-другому?</em></h2><p>По этим условиям вариантов нет. Измените количество гостей или сбросьте фильтры.</p><button class="btn" data-reset-filters>Сбросить фильтры ${icon('arrow')}</button></div>`;}
if(catalogForm){const q=new URLSearchParams(location.search),g=q.get('guests');if(g){const select=$('[name="guests"]',catalogForm);if(![...select.options].some(o=>o.value===g))select.add(new Option('От '+g+' гостей',g));select.value=g;}const a=q.get('arrival'),b=q.get('departure');if(a&&b&&/^\d{4}-\d{2}-\d{2}$/.test(a)&&/^\d{4}-\d{2}-\d{2}$/.test(b)&&b>a){$('#date-context').hidden=false;$('#date-context').textContent=`Ваши даты: ${prettyDate(a)} — ${prettyDate(b)}. Каталог подобран по вместимости. Наличие на даты уточняется у администратора.`;}catalogForm.addEventListener('input',renderCatalog);catalogForm.addEventListener('change',renderCatalog);catalogForm.addEventListener('submit',e=>e.preventDefault());catalogForm.addEventListener('reset',()=>{catalogType='all';$$('[data-type]').forEach(b=>{b.classList.toggle('active',b.dataset.type==='all');b.setAttribute('aria-pressed',b.dataset.type==='all');});queueMicrotask(renderCatalog);});renderCatalog();}
const lightbox=$('#lightbox');let activePhotos=[],photoIndex=0;
function getGallery(name){if(name==='detail')return DATA.catalog.find(c=>c.route===route)?.photos||[];if(name==='restaurant')return page('/restoran').photos;if(name==='home')return [DATA.images.river,DATA.images.gallery[0],DATA.images.pool];return currentPhotos;}
function showPhoto(){const im=$('img',lightbox);im.src=url(activePhotos[photoIndex]);im.alt=`Фотография ${photoIndex+1} из ${activePhotos.length} — Тихая Гавань`;$('figcaption',lightbox).textContent=`${photoIndex+1} / ${activePhotos.length} · Фотографии с официального сайта`;$('[aria-label="Предыдущая фотография"]',lightbox).hidden=activePhotos.length<2;$('[aria-label="Следующая фотография"]',lightbox).hidden=activePhotos.length<2;}
let currentPhotos=[];function renderPhotos(type='all'){const choices=type==='all'?[DATA.images.hero,DATA.images.river,DATA.images.pool,...DATA.images.gallery,...DATA.catalog.filter(c=>['bath','veranda'].includes(c.type)).flatMap(c=>c.photos.slice(0,2))]:DATA.catalog.filter(c=>c.type===type).flatMap(c=>c.photos.slice(0,3));currentPhotos=[...new Set(choices.filter(Boolean))];$('#photo-grid').innerHTML=currentPhotos.map((im,i)=>`<button class="gallery-open" data-gallery="all" data-index="${i}" aria-label="Открыть фотографию ${i+1}">${image(im,'Тихая Гавань — фото '+(i+1))}${icon('expand')}</button>`).join('');}if($('#photo-grid'))renderPhotos();
const dialog=$('#inquiry-dialog');
function openInquiry(context,review=false){const q=new URLSearchParams(location.search);$('#inquiry-content').innerHTML=`<span class="eyebrow">${review?'ВАШИ ВПЕЧАТЛЕНИЯ':'ПЕРВЫЙ ШАГ К ХОРОШЕМУ ОТДЫХУ'}</span><h2 id="inquiry-title">${review?'Поделиться <em>впечатлением.</em>':'Давайте <em>договоримся.</em>'}</h2><p class="muted">${review?'Подготовьте отзыв для отправки администрации по почте.':'Укажите пожелания — подготовим сообщение для администратора.'}</p><form id="inquiry-form"><label>${review?'Тема':'Что вас интересует'}<input name="context" value="${esc(context)}" required maxlength="150"></label><div class="form-row"><label>Ваше имя<input name="name" autocomplete="given-name" placeholder="Как к вам обращаться" required maxlength="80"></label><label>Телефон<input type="tel" name="phone" autocomplete="tel" placeholder="+7 (___) ___-__-__" ${review?'':'required'} minlength="10" maxlength="30"></label></div>${review?'':`<div class="form-row"><label>Заезд / дата события<input type="date" name="arrival" value="${esc(q.get('arrival')||'')}"></label><label>Выезд<input type="date" name="departure" value="${esc(q.get('departure')||'')}"></label></div><label>Количество гостей<input type="number" name="guests" min="1" max="500" value="${esc(q.get('guests')||'2')}" required></label>`}<label>${review?'Ваш отзыв':'Пожелания'}<textarea name="message" rows="3" maxlength="2000" placeholder="${review?'Расскажите о поездке':'Что для вас важно?'}" ${review?'required':''}></textarea></label><label class="consent"><input type="checkbox" required><span>Я согласен передать указанные данные выбранному сервису связи и ознакомлен с ${link('/politika-konfidenczialnosti/','информацией о конфиденциальности')}.</span></label><p class="form-error" aria-live="polite"></p><button class="btn">Подготовить ${review?'отзыв':'заявку'} ${icon('arrow')}</button><p class="small muted">После подготовки вы сами выберете способ отправки. Бронирование подтверждает администратор.</p></form>`;dialog.setAttribute('aria-labelledby','inquiry-title');const form=$('#inquiry-form');setupDates(form);const selectedObject=DATA.catalog.find(c=>c.title===context);if(['bath','veranda','event'].includes(selectedObject?.type)||/Ресторан|банкет|меню|питание/i.test(context)){form.dataset.singleDate='true';const departure=$('[name="departure"]',form);if(departure){departure.closest('label').hidden=true;departure.disabled=true;departure.value='';}const arrival=$('[name="arrival"]',form);if(arrival)arrival.closest('label').firstChild.textContent='Дата посещения / события';}form.addEventListener('submit',e=>{e.preventDefault();if(!datesValid(form))return;const f=new FormData(form),phone=String(f.get('phone')||'');if(!review&&(!/^[+\d\s().-]+$/.test(phone)||phone.replace(/\D/g,'').length<10||phone.replace(/\D/g,'').length>15)){$('.form-error',form).textContent='Укажите телефон: не менее 10 цифр.';return;}const message=[review?'Отзыв о Тихой Гавани':'Здравствуйте! Хочу уточнить условия отдыха в Тихой Гавани.',`Тема: ${f.get('context')}`,`Имя: ${f.get('name')}`,phone?`Телефон: ${phone}`:'',!review?`Заезд / событие: ${prettyDate(f.get('arrival'))}\nВыезд: ${prettyDate(f.get('departure'))}\nГостей: ${f.get('guests')}`:'',f.get('message')?`\n${f.get('message')}`:''].filter(Boolean).join('\n');$('#inquiry-content').innerHTML=`<span class="eyebrow">ВСЁ ГОТОВО К ОТПРАВКЕ</span><h2 id="inquiry-title">${review?'Отзыв':'Заявка'} <em>подготовлен${review?'':'а'}.</em></h2><p>Сообщение ещё не отправлено. Выберите удобный способ связи и отправьте его администратору.</p><pre class="message-preview">${esc(message)}</pre><div class="send-actions">${!review?ext('https://wa.me/79272191586?text='+encodeURIComponent(message),'Отправить в WhatsApp ↗','btn'):''}<a class="btn ${review?'':'btn-outline'}" href="mailto:turbaza63@yandex.ru?subject=${encodeURIComponent(review?'Отзыв о Тихой Гавани':'Заявка: '+f.get('context'))}&body=${encodeURIComponent(message)}">Отправить по почте ${icon('mail')}</a></div><p class="small muted">${review?'Публикацию отзыва решает администрация.':'Стоимость и наличие подтвердит администратор. Подготовка сообщения не резервирует даты.'}</p><button class="text-button" data-edit-inquiry>Изменить заявку</button>`;$('[data-edit-inquiry]').addEventListener('click',()=>{const previous=Object.fromEntries(f);openInquiry(context,review);for(const [k,v]of Object.entries(previous)){const input=$(`[name="${k}"]`,$('#inquiry-form'));if(input)input.value=v;}});});if(!dialog.open)dialog.showModal();}
let toastTimer;function toast(text){$('.toast').textContent=text;$('.toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('.toast').classList.remove('show'),2400);}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-gallery]');if(!b)return;if(b.matches('[data-inquire]'))openInquiry(b.dataset.inquire);if(b.matches('[data-review]'))openInquiry('Отзыв о поездке',true);if(b.matches('.dialog-close'))dialog.close();if(b.matches('.menu-button')){const expanded=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',expanded);b.setAttribute('aria-label',expanded?'Закрыть меню':'Открыть меню');$('#navigation').classList.toggle('open',expanded);}if(b.matches('[data-favorite]')){const key=b.dataset.favorite;favorites=favorites.includes(key)?favorites.filter(f=>f!==key):[...favorites,key];try{localStorage.setItem('gavan:favorites',JSON.stringify(favorites));}catch{}$$('[data-favorite]').filter(x=>x.dataset.favorite===key).forEach(x=>{x.classList.toggle('is-saved',favorites.includes(key));x.setAttribute('aria-pressed',favorites.includes(key));x.setAttribute('aria-label',(favorites.includes(key)?'Убрать из избранного: ':'В избранное: ')+DATA.catalog.find(c=>c.route===key).title);});toast(favorites.includes(key)?'Добавлено в избранное':'Удалено из избранного');if(catalogForm&&$('[name="saved"]',catalogForm).checked)renderCatalog();}if(b.matches('[data-type]')){catalogType=b.dataset.type;$$('[data-type]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});renderCatalog();}if(b.matches('[data-reset-filters]'))catalogForm.reset();if(b.matches('[data-home-type]')){$$('[data-home-type]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});$('#home-stays').innerHTML=DATA.catalog.filter(c=>c.type===b.dataset.homeType).slice(0,3).map(card).join('');}if(b.matches('[data-photo-type]')){$$('[data-photo-type]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});renderPhotos(b.dataset.photoType);}if(b.matches('[data-gallery]')){activePhotos=getGallery(b.dataset.gallery);photoIndex=Number(b.dataset.index)||0;if(activePhotos.length){showPhoto();lightbox.showModal();}}if(b.matches('.lightbox-close'))lightbox.close();if(b.matches('.lightbox-prev')){photoIndex=(photoIndex-1+activePhotos.length)%activePhotos.length;showPhoto();}if(b.matches('.lightbox-next')){photoIndex=(photoIndex+1)%activePhotos.length;showPhoto();}if(b.matches('.to-top'))window.scrollTo({top:0,behavior:'smooth'});});
for(const modal of [dialog,lightbox])modal.addEventListener('click',e=>{if(e.target===modal){const box=modal.getBoundingClientRect();if(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom)modal.close();}});
document.addEventListener('keydown',e=>{if(lightbox.open&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();photoIndex=(photoIndex+(e.key==='ArrowLeft'?-1:1)+activePhotos.length)%activePhotos.length;showPhoto();}if(e.key==='Escape'){$('#navigation').classList.remove('open');$('.menu-button').setAttribute('aria-expanded','false');$$('.nav-more').forEach(d=>d.open=false);}});
document.addEventListener('click',e=>{$$('.nav-more[open]').forEach(d=>{if(!d.contains(e.target))d.open=false;});});
window.addEventListener('scroll',()=>$('.to-top').classList.toggle('visible',scrollY>650),{passive:true});
